impl Encoding {
    /// How many encodings there are.
    pub const COUNT: usize = 4746;

    /// The encoding at an index below `COUNT`.
    pub fn from_index(index: usize) -> Option<Encoding> {
        ENCODINGS.get(index).copied()
    }

    /// The variant name: `Add32AddsubImm`, `Cmp64sAddsubImm`.
    pub fn name(self) -> &'static str {
        exarmo_core::names::name_at(ENCODING_TEXT, &ENCODING_ENDS, self as usize)
    }

    /// The mnemonic the encoding is written with.
    pub fn mnemonic(self) -> Mnemonic {
        MNEMONIC_OF[self as usize]
    }

    /// How many bytes of the instruction stream the encoding is.
    pub const fn length(self) -> u8 {
        4
    }
}

