impl Mnemonic {
    /// How many mnemonics there are.
    pub const COUNT: usize = 1724;

    /// The mnemonic at an index below `COUNT`.
    pub fn from_index(index: usize) -> Option<Mnemonic> {
        MNEMONICS.get(index).copied()
    }

    /// The mnemonic as the assembly writes it, in lower case.
    pub fn name(self) -> &'static str {
        exarmo_core::names::name_at(MNEMONIC_TEXT, &MNEMONIC_ENDS, self as usize)
    }
}

